// Helper to build replacement HTML
function buildContent(data, isSummary) {
  if (isSummary) {
    return `<div class="notes-section">
<h2>Last-Minute Revision Summary</h2>
<ul>
${data.s.map(s => `<li>${s}</li>`).join('\n')}
</ul>
</div>
<div class="exam-tips">
<h2>Quick Exam Tips</h2>
<ul>
${data.t.map(t => `<li>${t}</li>`).join('\n')}
</ul>
</div>`;
  }
  return `<div class="notes-section">
<h2>Detailed Notes</h2>
${data.d}
</div>
<div class="summary-box">
<h2>Last-Minute Summary</h2>
<ul>
${data.s.map(s => `<li>${s}</li>`).join('\n')}
</ul>
</div>
<div class="exam-tips">
<h2>Exam Tips</h2>
<ul>
${data.t.map(t => `<li>${t}</li>`).join('\n')}
</ul>
</div>`;
}

// Extract topic key from filename like edexcel-biology-eb1-gcse
function getTopicKey(base) {
  const parts = base.split('-');
  return parts[parts.length - 1];
}

let enriched = 0;
let skipped = 0;
let noMatch = 0;

const files = fs.readdirSync(notesDir).filter(f => f.endsWith('.html'));

for (const file of files) {
  const filepath = path.join(notesDir, file);
  let html = fs.readFileSync(filepath, 'utf8');

  // Check if this file has generic content
  const hasGeneric = html.toLowerCase().includes('covers fundamental concepts essential for') ||
                     html.toLowerCase().includes('examiners frequently test') ||
                     html.toLowerCase().includes('connect theoretical knowledge to real-world') ||
                     html.toLowerCase().includes('practical applications') ||
                     html.includes('Coming Soon') ||
                     html.includes('coming-soon');

  if (!hasGeneric) { skipped++; continue; }

  const basename = file.replace(/\.html$/, '');
  const isSummary = basename.endsWith('-summary');
  let base = isSummary ? basename.slice(0, -8) : basename;

  // Remove level suffix
  if (base.endsWith('-a')) base = base.slice(0, -2);
  else if (base.endsWith('-igcse')) base = base.slice(0, -6);
  else if (base.endsWith('-ial')) base = base.slice(0, -4);
  else if (base.endsWith('-gcse')) base = base.slice(0, -5);
  else if (base.endsWith('-hl')) base = base.slice(0, -3);
  else if (base.endsWith('-sl')) base = base.slice(0, -3);

  const tkey = getTopicKey(base);
  const data = QUICK[tkey];
  if (!data) { noMatch++; continue; }

  const newContent = buildContent(data, isSummary);

  // Find header end and section end
  const headerIdx = html.indexOf('<div class="notes-header">');
  if (headerIdx === -1) { skipped++; continue; }
  const headerEnd = html.indexOf('</div>', html.indexOf('</div>', headerIdx) + 6);
  if (headerEnd === -1) { skipped++; continue; }
  const sectionMatch = html.match(/<\/div>\s*<\/div>\s*<\/section>/);
  if (!sectionMatch) { skipped++; continue; }

  const before = html.substring(0, headerEnd + 6);
  const after = html.substring(sectionMatch.index);
  fs.writeFileSync(filepath, before + '\n' + newContent + '\n' + after);
  enriched++;
}

console.log(`Enriched: ${enriched}`);
console.log(`Skipped: ${skipped}`);
console.log(`No match: ${noMatch}`);
console.log(`Total: ${files.length}`);
